                                                                                                                                                                                                                                                                                                function efeitoEntrada(){



                                                                                                                                                                                                                                                                                                const janelas =
                                                                                                                                                                                                                                                                                                document.querySelectorAll(".janela");



                                                                                                                                                                                                                                                                                                janelas.forEach((janela,index)=>{


                                                                                                                                                                                                                                                                                                janela.style.animationDelay =
                                                                                                                                                                                                                                                                                                (index * 0.1)+"s";



                                                                                                                                                                                                                                                                                                });



                                                                                                                                                                                                                                                                                                }



                                                                                                                                                                                                                                                                                                window.addEventListener(

                                                                                                                                                                                                                                                                                                "load",

                                                                                                                                                                                                                                                                                                efeitoEntrada

                                                                                                                                                                                                                                                                                                );
